'use client';
import { useEffect, useRef, useState, type AnimationEvent } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useReducedMotion } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Avatar, enter, Seg, Spin, Tip, useGrow } from '../lib/motion';
import { useHoverGlide } from '../lib/glide';
import '../designme.css';
import './ticket-list.css';

export type TicketListPriority = 'urgent' | 'high' | 'normal' | 'low';
export type TicketListStatus = 'open' | 'done';

export interface TicketListTicket {
  id: string;
  /** What it is about, like "Figma frames not syncing" */
  title: string;
  /** Who asked, like "Lumen Labs" */
  from: string;
  /** What they wrote. Shown after the customer while the ticket is shut, and above the reply when it opens */
  question?: string;
  /** The reply the agent suggests. People can edit it before sending */
  reply?: string;
  /** The coloured dot in front, a vivid mark: urgent red, high orange, normal the accent, low grey */
  priority?: TicketListPriority;
  /** Who it is assigned to, shown as a small avatar */
  assignee: { initials: string; color: string };
  /** How long it has waited, like "4m" */
  waiting: string;
  status: TicketListStatus;
}

export interface TicketListProps {
  /** The tickets. Leave it out to let Send and solve move them to Solved by itself */
  tickets?: TicketListTicket[];
  defaultTickets?: TicketListTicket[];
  onTicketsChange?: (tickets: TicketListTicket[]) => void;
  /** Which tickets show. Leave it out to let the switch change it */
  filter?: TicketListStatus;
  defaultFilter?: TicketListStatus;
  onFilterChange?: (filter: TicketListStatus) => void;
  /** The id of the open ticket, or null. Leave it out to let the rows open and shut */
  open?: string | null;
  defaultOpen?: string | null;
  onOpenChange?: (id: string | null) => void;
  /** Sends the reply, edited or not. Return a promise and the button spins until it settles; then the ticket fades out and is solved */
  onSend?: (ticket: TicketListTicket, reply: string) => void | Promise<void>;
  title?: string;
  /** The switch's two labels */
  filterLabels?: Record<TicketListStatus, string>;
  /** The empty state's title when no ticket matches the filter. Defaults to "All caught up" for open tickets and "Nothing solved yet" */
  emptyLabel?: string;
  /** The empty state's quiet line. Defaults to "New tickets show up here" and "Solved tickets show up here" */
  emptyHint?: string;
  replyLabel?: string;
  editLabel?: string;
  sendLabel?: string;
  className?: string;
}

const PRIORITY: Record<TicketListPriority, string> = { urgent: 'Urgent', high: 'High', normal: 'Normal', low: 'Low' };

// how long a solved ticket takes to fade, then to fold its height away
const FADE = 330, FOLD = 260;

function Ticket({ ticket, index, isOpen, leaving, busy, onToggle, onSend, labels }: {
  ticket: TicketListTicket; index: number; isOpen: boolean; leaving: boolean; busy: boolean;
  onToggle: () => void; onSend: (reply: string) => void; labels: { reply: string; edit: string; send: string };
}) {
  // rows come in one after another, then drop the entrance so a later fade-out starts on time
  const [entering, setEntering] = useState(true);
  const text = useRef<HTMLDivElement>(null);
  const row = useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();
  // a solved ticket fades, then folds its height away, so the tickets under it slide up instead of jumping
  useEffect(() => {
    const el = row.current; if (!leaving || !el || reduce) return;
    el.style.overflow = 'hidden';
    const a = el.animate([{ height: el.offsetHeight + 'px' }, { height: '0px' }], { duration: FOLD, delay: FADE, easing: 'cubic-bezier(.22,1,.36,1)', fill: 'forwards' });
    return () => a.cancel();
  }, [leaving, reduce]);
  const p = ticket.priority ?? 'normal';
  const edit = () => {
    const el = text.current; if (!el) return;
    el.focus();
    const sel = document.getSelection(); sel?.selectAllChildren(el); sel?.collapseToEnd();
  };
  return (
    <div ref={row} className={cx('dm-tkx-t', isOpen && 'dm-open', entering && 'dm-enter', leaving && 'dm-leave')} style={entering ? enter(index * 40).style : undefined}
      onAnimationEnd={(e: AnimationEvent) => { if (e.target === e.currentTarget && entering) setEntering(false); }}>
      <button type="button" className="dm-tkx-r" aria-expanded={isOpen} onClick={leaving ? undefined : onToggle}>
        <Tip label={PRIORITY[p]}><span className="dm-pr"><span className="dm-dot" data-p={p} /></span></Tip>
        <span className="dm-t"><b>{ticket.title}</b><span>{ticket.from}{ticket.question && !isOpen ? ' · ' + ticket.question : ''}</span></span>
        <span className="dm-m"><span className="dm-w">{ticket.waiting}</span><Avatar initials={ticket.assignee.initials} color={ticket.assignee.color} /></span>
      </button>
      {isOpen && (
        <div className="dm-tkx-d">
          <div className="dm-tkx-q dm-enter" style={enter(0).style}>{ticket.question}</div>
          <div className="dm-tkx-s dm-enter" style={enter(50).style}>
            <div className="dm-lb"><Icon name="spark" size="xs" />{labels.reply}</div>
            <div ref={text} className="dm-tx" contentEditable suppressContentEditableWarning spellCheck={false}>{ticket.reply}</div>
          </div>
          <div className="dm-tkx-a dm-enter" style={enter(100).style}>
            <button type="button" className="dm-pill dm-ghost dm-sm" onClick={edit}><Icon name="edit" size="xs" />{labels.edit}</button>
            {/* while it sends, a spinner takes the icon's place and the words stay, so the button keeps its width */}
            <button type="button" className="dm-pill dm-accent dm-sm" aria-busy={busy} onClick={() => { if (!busy) onSend(text.current?.textContent ?? ticket.reply ?? ''); }}>
              {busy ? <Spin /> : <Icon name="send" size="xs" />}{labels.send}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/** Support tickets the agent has triaged, with suggested replies. */
export function TicketList({ tickets, defaultTickets = [], onTicketsChange, filter, defaultFilter = 'open', onFilterChange, open, defaultOpen = null, onOpenChange, onSend,
  title = 'Support', filterLabels = { open: 'Open', done: 'Solved' }, emptyLabel, emptyHint, replyLabel = 'Suggested reply', editLabel = 'Edit', sendLabel = 'Send and solve', className }: TicketListProps) {
  const [list, setList] = useControllable(tickets, defaultTickets, onTicketsChange);
  const [shown, setShown] = useControllable(filter, defaultFilter, onFilterChange);
  const [openId, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [busy, setBusy] = useState<string | null>(null);
  const [leaving, setLeaving] = useState<string | null>(null);
  const reduce = useReducedMotion();
  const alive = useRef(true);
  useEffect(() => () => { alive.current = false; }, []);
  // the latest list, for when a send settles after other changes
  const latest = useRef(list);
  useEffect(() => { latest.current = list; });

  const send = async (t: TicketListTicket, reply: string) => {
    setBusy(t.id);
    try { await onSend?.(t, reply); } catch { if (alive.current) setBusy(null); return; }
    if (!alive.current) return;
    setLeaving(t.id);
    await new Promise(res => setTimeout(res, reduce ? 0 : FADE + FOLD));
    if (!alive.current) return;
    setBusy(null); setLeaving(null); setOpen(null);
    setList(latest.current.map(x => x.id === t.id ? { ...x, status: 'done', reply } : x));
  };
  const rows = list.filter(t => t.status === shown);
  // the card eases to its new height as tickets open, close, leave or change with the filter, and keeps no room for one to open
  const [box, boxIn] = useGrow();
  // Clean's one hover: a highlight that glides from ticket to ticket; the open one keeps its own fill
  useHoverGlide(box, '.dm-tkx-r', { keep: ':not(*)' });

  return (
    <div data-dm="" ref={box} className={cx('dm-tkx dm-panel dm-growing', className)}><div ref={boxIn} className="dm-grow">
      <div className="dm-tkx-h">
        <b>{title}</b>
        <Seg className="dm-tkx-sg" label="Filter" value={shown} onChange={v => { setOpen(null); setShown(v); }}
          options={[{ value: 'open', label: filterLabels.open }, { value: 'done', label: filterLabels.done }]} />
      </div>
      {/* a new filter brings its rows in again */}
      <div className="dm-tkx-list" key={shown}>
        {rows.length ? rows.map((t, i) => (
          <Ticket key={t.id} ticket={t} index={i} isOpen={openId === t.id} leaving={leaving === t.id} busy={busy === t.id}
            onToggle={() => setOpen(openId === t.id ? null : t.id)} onSend={reply => send(t, reply)}
            labels={{ reply: replyLabel, edit: editLabel, send: sendLabel }} />
        )) : <div className="dm-tkx-em"><span className="dm-tkx-em-art" aria-hidden="true" /><b>{emptyLabel ?? (shown === 'open' ? 'All caught up' : 'Nothing solved yet')}</b><span>{emptyHint ?? (shown === 'open' ? 'New tickets show up here' : 'Solved tickets show up here')}</span></div>}
      </div>
    </div></div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Ticket list ---------- */
/* support tickets the agent has triaged. Its content sits 16px in from every edge in every style: the title and the switch in
   the head, then the tickets, each a row whose hover fill reaches out 8px round its dot and words with the card's rounding
   (never a sharp band across the card). An open ticket shows the question and the suggested reply on the title's column,
   with no band behind it; the reply is a field you can edit, and Send and solve ends on the content's right edge. The card
   grows and shrinks with what it shows (grow()), so it keeps no room for a ticket to open */
.dm-tkx{padding:var(--dm-s-4) var(--dm-s-4) var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-tkx-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);min-height:28px;font-size:14px}
.dm-tkx-h b{font-weight:500}
.dm-tkx-sg button{font-size:12px;height:24px;padding:0 10px}
.dm-tkx-list{display:flex;flex-direction:column;gap:2px;margin:0 calc(-1 * var(--dm-s-2))}
.dm-tkx :is(.dm-pill,.dm-ib):active{transform:none}
.dm-tkx-r{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;width:100%;padding:var(--dm-s-2);border-radius:calc(var(--dm-r-card) - 8px);text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-tkx-r:hover{background:color-mix(in srgb,var(--dm-fg) 4%,transparent)}}
.dm-tkx-r .dm-pr{display:flex;align-items:center;justify-content:center;width:18px;height:18px}
.dm-tkx-r .dm-pr .dm-dot{width:8px;height:8px}
.dm-tkx-r .dm-t{display:flex;flex-direction:column;min-width:0;font-size:13px}
.dm-tkx-r .dm-t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-tkx-r .dm-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-tkx-r .dm-m{display:flex;align-items:center;gap:6px}
.dm-tkx-r .dm-m .dm-av{width:20px;height:20px;font-size:9px}
.dm-tkx-r .dm-w{font-size:11.5px;color:var(--dm-muted)}
/* a ticket's priority is a vivid mark, 3:1 on the surface: urgent red, high orange, normal the accent's mark, low a grey that
   holds 3:1 too */
.dm-tkx-r .dm-dot[data-p="urgent"]{color:var(--dm-bad-mark)}.dm-tkx-r .dm-dot[data-p="high"]{color:var(--dm-warn-mark)}.dm-tkx-r .dm-dot[data-p="normal"]{color:var(--dm-accent-mark,var(--dm-accent))}.dm-tkx-r .dm-dot[data-p="low"]{color:color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface))}
.dm-tkx-d{padding:4px var(--dm-s-2) var(--dm-s-3) 36px;display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-tkx-q{font-size:12.5px;line-height:1.5;color:var(--dm-fg2)}
/* the suggested reply is a field: a quiet grey edge at rest, one step stronger while you edit it, and nothing else changes */
.dm-tkx-s{padding:10px var(--dm-s-3) var(--dm-s-3);border-radius:var(--dm-r-box);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font-size:12.5px;line-height:1.5;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
.dm-tkx-s:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
@supports (corner-shape:squircle){.dm-tkx-s{corner-shape:squircle;border-radius:var(--dm-r-box-sq)}}
.dm-tkx-s .dm-lb{display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--dm-accent-fg,var(--dm-accent));font-weight:500;margin-bottom:var(--dm-s-1)}
/* the reply reads as text you can edit: the text cursor over it, and an accent caret once it has focus */
.dm-tkx-s [contenteditable]{outline:0;cursor:text;caret-color:var(--dm-accent-fg,var(--dm-accent))}
.dm-tkx-a{display:flex;gap:var(--dm-s-2);justify-content:flex-end}
/* nothing left in a view: the empty state, a small sketch of a list on a card, a title and one muted line */
.dm-tkx-em{display:flex;flex-direction:column;align-items:center;gap:4px;padding:var(--dm-s-4) var(--dm-s-2) var(--dm-s-5);text-align:center}
.dm-tkx-em b{font-size:13.5px;line-height:18px;font-weight:500;color:var(--dm-fg)}
.dm-tkx-em>span:not(.dm-tkx-em-art){max-width:290px;font-size:12.5px;line-height:1.5;color:var(--dm-muted)}
.dm-tkx-em-art{position:relative;display:block;width:136px;height:70px;margin:0 0 12px;border-radius:calc(10px * var(--dm-rk-l,var(--dm-rk)));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.dm-tkx-em-art::before{content:"";position:absolute;left:14px;top:16px;width:8px;height:8px;border-radius:50%;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 55%,var(--dm-surface)))}
.dm-tkx-em-art::after{content:"";position:absolute;left:32px;top:17px;width:58px;height:6px;border-radius:3px;background:var(--dm-ghost,var(--dm-chip));box-shadow:0 16px 0 var(--dm-ghost,var(--dm-chip)),0 32px 0 var(--dm-ghost-2,color-mix(in srgb,var(--dm-chip) 55%,var(--dm-surface)))}
:root:not([data-style="soft"],[data-style="clean"]) .dm-tkx-em-art:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){box-shadow:0 0 0 1px var(--dm-line)}
.dm-tkx-t.dm-leave{animation:dm-leave .35s var(--dm-ease) both}
/* Clean: the head is an off-white strip with the switch 16px from the card's top and right edges and the
   strip's hairline (owner, 23 Nov) and the title 16px in; the reply's label is grey like the rest of the chrome, and Edit is the flat
   secondary beside the ink Send and solve */
:root[data-style="clean"] .dm-tkx,:root [data-style="clean"] .dm-tkx,:root [data-style="clean"].dm-tkx{padding-top:0}
:root[data-style="clean"] .dm-tkx-h,:root [data-style="clean"] .dm-tkx-h,:root [data-style="clean"].dm-tkx-h{margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0;line-height:28px}
:root[data-style="clean"] .dm-tkx-s .dm-lb,:root [data-style="clean"] .dm-tkx-s .dm-lb,:root [data-style="clean"].dm-tkx-s .dm-lb{color:var(--dm-fg2)}
:root[data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost,:root [data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost,:root [data-style="clean"].dm-tkx-a .dm-pill.dm-ghost{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost:hover,:root [data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost:hover,:root [data-style="clean"].dm-tkx-a .dm-pill.dm-ghost:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost:active,:root [data-style="clean"] .dm-tkx-a .dm-pill.dm-ghost:active,:root [data-style="clean"].dm-tkx-a .dm-pill.dm-ghost:active{box-shadow:var(--dm-btn2-press)}
